insert into public.pages (key, fields, sections) values ('about', '{"headerPhoto":{"url":"/img/foto/cucina-lago-1600.webp","alt":""},"title":"Chi siamo","introTitle":"Cosa facciamo","intro1":"Siamo un''agenzia di rappresentanza: affianchiamo i rivenditori di arredamento e illuminazione dal primo contatto con un marchio fino all''assistenza dopo la vendita.","aboutPhoto":{"url":"/img/foto/libreria-1600.webp","alt":""},"teamTitle":"Le persone","teamSubtitle":"Gabriele e Francesca seguono personalmente ogni rivenditore e ogni progetto.","territoryTitle":"Dove lavoriamo","territoryText":"Da Imperia visitiamo i negozi della costa ligure e dell''entroterra piemontese.","territoryLiguria":"Imperia\nSavona\nGenova\nLa Spezia","territoryPiemonte":"Cuneo\nAsti\nAlessandria","seoTitle":"Chi siamo","seoDescription":"Gabriele Piccardo e Francesca Zabbia: chi c''è dietro Liguria Design Group, agenzia di rappresentanza arredamento a Imperia."}'::jsonb, '[{"title":"Rappresentanza marchi","text":"Facciamo conoscere ai negozi i marchi che rappresentiamo, con campioni, cataloghi e novità."},{"title":"Preventivi e progetti","text":"Progettiamo con 3CAD e Metron e prepariamo preventivi pronti da presentare al cliente finale."},{"title":"Forniture contract","text":"Per hotel, B&B, studentati e locali seguiamo la fornitura dal sopralluogo alla consegna."},{"title":"Assistenza","text":"Restiamo il riferimento per ordini, consegne e problemi anche dopo la vendita."}]'::jsonb) on conflict (key) do nothing;
insert into public.pages (key, fields, sections) values ('brands', '{"title":"I marchi","intro":"I marchi italiani di arredo, bagno, pannelli e illuminazione che portiamo nei negozi di Liguria e basso Piemonte.","seoTitle":"Marchi rappresentati","seoDescription":"Lapalma, Pintdecor, GB Group, Imab Group e gli altri marchi di arredamento rappresentati da Liguria Design Group in Liguria e basso Piemonte."}'::jsonb, '[]'::jsonb) on conflict (key) do nothing;
insert into public.pages (key, fields, sections) values ('contract', '{"headerPhoto":{"url":"/img/foto/ristorante-1600.webp","alt":""},"title":"Contract","intro":"Forniture per hotel, B&B, studentati, uffici e locali. Scegliamo i marchi, prepariamo il preventivo e seguiamo la consegna.","typesTitle":"Per chi lavoriamo","typesIntro":"Passate sopra un tipo di progetto per vedere un esempio.","brandsTitle":"Marchi per il contract","seoTitle":"Forniture contract per hotel e locali","seoDescription":"Arredamento e illuminazione contract in Liguria e basso Piemonte: hotel, B&B, studentati, uffici, ristoranti e bar."}'::jsonb, '[]'::jsonb) on conflict (key) do nothing;
insert into public.pages (key, fields, sections) values ('dealers', '{"title":"Per rivenditori","intro":"Avete un negozio di arredamento? Ecco cosa possiamo fare per voi.","servicesTitle":"Servizi","methodTitle":"Come lavoriamo","step1Title":"Ascoltiamo","step1Text":"cosa vende il negozio e cosa chiedono i suoi clienti.","step2Title":"Selezioniamo","step2Text":"i marchi adatti e portiamo i campioni.","step3Title":"Prepariamo","step3Text":"progetto e preventivo con 3CAD o Metron.","step4Title":"Restiamo","step4Text":"il riferimento per ordini, consegne e assistenza.","brandsTitle":"I marchi che portiamo","seoTitle":"Servizi per rivenditori di arredamento","seoDescription":"Cataloghi, listini, preventivi con 3CAD e Metron e visite in negozio per rivenditori di arredamento in Liguria e basso Piemonte."}'::jsonb, '[{"title":"Cataloghi","text":"Le collezioni aggiornate di ogni marchio.","cta":"Richiedi"},{"title":"Listini","text":"Prezzi riservati ai rivenditori, su richiesta.","cta":"Richiedi"},{"title":"Preventivi","text":"Progetto con 3CAD o Metron e preventivo pronto per il cliente.","cta":"Invia un progetto"},{"title":"Visita in negozio","text":"Campioni e novità, su appuntamento.","cta":"Prenota"}]'::jsonb) on conflict (key) do nothing;
insert into public.pages (key, fields, sections) values ('contact', '{"title":"Scriveteci","intro":"Raccontateci di cosa avete bisogno: vi rispondiamo noi, di persona.","seoTitle":"Contatti","seoDescription":"Contatta Liguria Design Group: Via Vittorio Alfieri 18, Imperia. Agenzia di rappresentanza arredamento per Liguria e basso Piemonte."}'::jsonb, '[]'::jsonb) on conflict (key) do nothing;
insert into public.pages (key, fields, sections) values ('privacy', '{}'::jsonb, '[{"title":"Titolare del trattamento","text":"Il titolare del trattamento dei dati è Liguria Design Group, Via Vittorio Alfieri 18, 18100 Imperia (IM), P.IVA 01587610088. Per qualsiasi richiesta è possibile scrivere a info@liguriadesigngroup.it."},{"title":"Dati raccolti","text":"Raccogliamo i dati che ci fornisci volontariamente tramite il modulo di contatto (nome, email, telefono se indicato, messaggio) e l''iscrizione alla newsletter (email). Non raccogliamo categorie particolari di dati."},{"title":"Finalità e base giuridica","text":"I dati di contatto sono trattati per rispondere alle tue richieste (base giuridica: esecuzione di misure precontrattuali). L''email per la newsletter è trattata sulla base del tuo consenso, revocabile in qualsiasi momento."},{"title":"Fornitori","text":"I dati sono conservati su Supabase (database) e il sito è ospitato su Vercel. I messaggi del modulo arrivano anche per email alla casella info@liguriadesigngroup.it."},{"title":"Conservazione","text":"I dati sono conservati per il tempo necessario alle finalità indicate e comunque non oltre i termini previsti dalla legge. Puoi richiederne la cancellazione in qualsiasi momento."},{"title":"Diritti dell''interessato","text":"Ai sensi degli artt. 15-22 del GDPR hai diritto di accesso, rettifica, cancellazione, limitazione, portabilità e opposizione. Per esercitarli, scrivi a info@liguriadesigngroup.it. Hai inoltre diritto di proporre reclamo al Garante per la protezione dei dati personali."}]'::jsonb) on conflict (key) do nothing;
insert into public.pages (key, fields, sections) values ('cookie', '{}'::jsonb, '[{"title":"Cosa sono i cookie","text":"I cookie sono piccoli file di testo che i siti visitati inviano al dispositivo dell''utente, dove vengono memorizzati per essere ritrasmessi agli stessi siti alla visita successiva."},{"title":"Cookie tecnici","text":"Il sito usa solo strumenti tecnici necessari al funzionamento, come la memoria della tua scelta sul consenso. Non richiedono consenso."},{"title":"Statistiche","text":"Solo se acconsenti, registriamo in forma anonima le pagine visitate per capire quali contenuti sono più utili. Non usiamo cookie di profilazione né strumenti pubblicitari."},{"title":"Gestione delle preferenze","text":"Puoi cambiare la tua scelta in qualsiasi momento dal link \"Preferenze cookie\" nel footer, oppure cancellando i dati del sito dalle impostazioni del browser."}]'::jsonb) on conflict (key) do nothing;
insert into public.pages (key, fields, sections) values ('terms', '{}'::jsonb, '[{"title":"Oggetto","text":"I presenti termini regolano l''utilizzo del sito di Liguria Design Group. Navigando il sito accetti le presenti condizioni."},{"title":"Proprietà intellettuale","text":"Tutti i contenuti del sito (testi, immagini, logo, marchi) sono di proprietà di Liguria Design Group o dei rispettivi titolari e non possono essere riprodotti senza autorizzazione."},{"title":"Limitazione di responsabilità","text":"Le informazioni presenti sul sito sono fornite a scopo informativo. Liguria Design Group non garantisce l''assenza di errori e non è responsabile per eventuali danni derivanti dall''uso del sito."},{"title":"Link a siti esterni","text":"Il sito può contenere link a siti di terzi, come i marchi rappresentati. Non siamo responsabili dei contenuti o delle policy di tali siti."},{"title":"Legge applicabile","text":"I presenti termini sono regolati dalla legge italiana. Per qualsiasi controversia è competente il foro di Imperia."}]'::jsonb) on conflict (key) do nothing;
insert into public.pages (key, fields, sections) values ('faq', '{}'::jsonb, '[{"title":"Di cosa si occupa Liguria Design Group?","text":"Siamo un''agenzia di rappresentanza nel settore mobili e illuminazione. Rappresentiamo aziende italiane e affianchiamo rivenditori e negozianti con consulenza, preventivi e assistenza quotidiana."},{"title":"Come posso diventare rivenditore o richiedere una consulenza?","text":"Scriveteci dal modulo nella pagina Contatti: vi ricontattiamo per valutare insieme la collaborazione."},{"title":"Fate anche forniture contract?","text":"Sì. Seguiamo hotel, B&B, studentati, uffici e locali che hanno bisogno di forniture importanti di arredamento e illuminazione."},{"title":"In quali zone lavorate?","text":"In Liguria e nel basso Piemonte. Per richieste fuori zona scriveteci e valutiamo insieme."},{"title":"Con quali software progettate?","text":"Usiamo 3CAD e Metron per progetti e preventivi pronti da presentare al cliente finale."},{"title":"Posso avere cataloghi e listini?","text":"Sì, se siete un rivenditore. Chiedeteli dalla pagina Per rivenditori o dal modulo di contatto indicando i marchi che vi interessano."}]'::jsonb) on conflict (key) do nothing;
